 "content": "from collections import Counter

def transform(grid):
    """Extend each nonempty row's rightmost foreground run to the right edge in color 1."""
    if not grid:
        return []
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    out = [row[:] for row in grid]
    for row in out:
        inds = [i for i, value in enumerate(row) if value != bg]
        if inds:
            last = max(inds)
            for c in range(last + 1, len(row)):
                row[c] = 1
    return out

